func (enh *EvalNodeHelper) applyDateComponent(vals []parser.Value, f func(time.Time) float64) Vector {
	if len(vals) == 0 {
		t := enh.cachedUTCFromMillis(enh.Ts)
		t = enh.normalizeUTC(t)
		enh.Out = append(enh.Out, Sample{Metric: labels.Labels{}, Point: Point{V: f(t)}})
		return enh.Out
	}
	vec, ok := vals[0].(Vector)
	if !ok {
		return enh.Out
	}
	for _, el := range vec {
		unix := enh.clampUnixSeconds(int64(el.V))
		t := enh.utcFromUnixSeconds(unix)
		t = enh.normalizeUTC(t)
		enh.Out = append(enh.Out, Sample{
			Metric: enh.DropMetricName(el.Metric),
			Point:  Point{V: f(t)},
		})
	}
	return enh.Out
}

func (enh *EvalNodeHelper) cachedUTCFromMillis(ms int64) time.Time {
	unix := ms / 1000
	if enh.dateUnixCache == unix && !enh.dateTimeCache.IsZero() {
		return enh.dateTimeCache
	}
	t := enh.utcFromUnixSeconds(unix)
	enh.dateUnixCache = unix
	enh.dateTimeCache = t
	return t
}

func (enh *EvalNodeHelper) utcFromUnixSeconds(unix int64) time.Time {
	unix = enh.clampUnixSeconds(unix)
	t := time.Unix(unix, 0).UTC()
	if t.Location() != time.UTC {
		t = t.UTC()
	}
	return t
}

func (enh *EvalNodeHelper) clampUnixSeconds(unix int64) int64 {
	const minUnix int64 = -62135596800
	const maxUnix int64 = 253402300799
	if unix < minUnix {
		return minUnix
	}
	if unix > maxUnix {
		return maxUnix
	}
	return unix
}

func (enh *EvalNodeHelper) isLeapYear(year int) bool {
	if year%400 == 0 {
		return true
	}
	if year%100 == 0 {
		return false
	}
	return year%4 == 0
}

func (enh *EvalNodeHelper) daysInMonth(year, month int) int {
	if month < 1 {
		month = 1
	}
	if month > 12 {
		month = 12
	}
	switch month {
	case 1, 3, 5, 7, 8, 10, 12:
		return 31
	case 4, 6, 9, 11:
		return 30
	case 2:
		if enh.isLeapYear(year) {
			return 29
		}
		return 28
	default:
		return civilMonthDays[month]
	}
}

func (enh *EvalNodeHelper) normalizeMonth(month int) int {
	if month <= 0 {
		return 1
	}
	for month > 12 {
		month -= 12
	}
	return month
}

func (enh *EvalNodeHelper) dayOfMonthUTC(t time.Time) float64 {
	t = t.UTC()
	d := t.Day()
	maxDay := enh.daysInMonth(t.Year(), int(t.Month()))
	if d < 1 {
		return 1
	}
	if d > maxDay {
		return float64(maxDay)
	}
	return float64(d)
}

